coder.implementation:
constexpr uint32_t kFirstStepUs = 1u;
constexpr uint32_t kCapUs = 64u;
constexpr uint32_t kAbortCountCap = 64u;
constexpr uint32_t kImmediateAborts = 2u;
constexpr uint32_t kSpinAttempts = 4u;
constexpr uint32_t kShortWaitAttempts = 12u;
constexpr uint32_t kMaxLockAttempts = 20u;

struct PolicyState {
  uint32_t consecutive_aborts = 0u;
  uint32_t window_us = 0u;
};

uint32_t grow_window(uint32_t current) noexcept {
  if (current == 0u) {
    return kFirstStepUs;
  }
  return std::min(current * 2u, kCapUs);
}

uint32_t jittered_wait(uint32_t window, uint32_t jitter) noexcept {
  uint32_t half = window >> 1u;
  return half + ((jitter * (window - half)) >> 16u);
}

uint32_t policy_after_abort(PolicyState& state, const izanagi_silo_api::AbortContext& ctx) noexcept {
  state.consecutive_aborts = std::min(state.consecutive_aborts + 1u, kAbortCountCap);
  if (state.consecutive_aborts < kImmediateAborts) {
    return 0u;
  }
  state.window_us = grow_window(state.window_us);
  uint32_t jitter = static_cast<uint32_t>(ctx.rand & 65535u);
  return jittered_wait(state.window_us, jitter);
}

izanagi_silo_api::LockResponse policy_on_lock_conflict(PolicyState&, const izanagi_silo_api::LockContext& ctx) noexcept {
  uint32_t attempt = static_cast<uint32_t>(ctx.attempt);
  if (attempt >= kMaxLockAttempts) {
    return izanagi_silo_api::LockResponse{izanagi_silo_api::PolicyAction::abort, 0u};
  }
  if (attempt < kSpinAttempts) {
    return izanagi_silo_api::LockResponse{izanagi_silo_api::PolicyAction::retry, 0u};
  }
  if (attempt < kShortWaitAttempts) {
    return izanagi_silo_api::LockResponse{izanagi_silo_api::PolicyAction::retry, 1u};
  }
  return izanagi_silo_api::LockResponse{izanagi_silo_api::PolicyAction::retry, 2u};
}

void policy_on_commit(PolicyState& state, const izanagi_silo_api::CommitContext&) noexcept {
  state.consecutive_aborts = 0u;
  state.window_us = state.window_us >> 1u;
}
